pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource} from "../src/MStableYieldSource.sol";
import {ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }
    function testFuzz_property(address caller, address beneficiary, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(beneficiary != address(0));
        vm.assume(caller != beneficiary);
        vm.assume(caller != address(c));
        vm.assume(beneficiary != address(c));
        vm.assume(caller != address(this));
        vm.prank(caller);
        c.supplyTokenTo(amount, beneficiary);
        // General rule: credits for a supply driven by caller `caller` for beneficiary
        // `beneficiary` accrue to the beneficiary, so the beneficiary's imBalances
        // strictly exceeds the caller's (which stays at zero) for any a != b.
        assertTrue(c.imBalances(beneficiary) > c.imBalances(caller));
    }
}
